{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { validDueDate } from './public/date.js';
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
    default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High')),
    due_date TEXT NOT NULL DEFAULT ''
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
`);
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  database.exec(`
    ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
    UPDATE tasks SET position = id;
  `);
}
// Keep each project's established positions even while its tasks are elsewhere.
database.exec(`
  CREATE TABLE IF NOT EXISTS task_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id),
    project_id INTEGER NOT NULL REFERENCES projects(id),
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id),
    UNIQUE (project_id, position)
  );
  INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
    SELECT id, project_id, position FROM tasks;
`);
const projectQuery = `SELECT id, name, archived, default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND completed = 1) AS completed
  FROM projects`;
const listProjects = database.prepare(`${projectQuery} ORDER BY id`);
const getProject = database.prepare(`${projectQuery} WHERE id = ?`);
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateDefaultPriority = database.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const listTasks = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
const getTask = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const createTask = database.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = ?))`);
const rememberCreatedTask = database.prepare(`INSERT INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks WHERE id = ?`);
const rememberDestination = database.prepare(`INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  VALUES (?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = ?))`);
const moveTask = database.prepare(`UPDATE tasks
  SET position = (SELECT position FROM task_positions WHERE task_id = ? AND project_id = ?), project_id = ?
  WHERE project_id = ? AND id = ?`);
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const updateTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');

function transaction(action) {
  database.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    database.exec('COMMIT');
    return result;
  } catch (error) {
    database.exec('ROLLBACK');
    throw error;
  }
}

function taskData(task) {
  return { ...task, completed: Boolean(task.completed) };
}

async function readInput(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 65536) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const assets = new Map([
  ['/date.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/date.js', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/styles.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/styles.css', import.meta.url))]],
]);
const page = readFileSync(new URL('./public/index.html', import.meta.url));

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

const server = http.createServer(async (request, response) => {
  const path = new URL(request.url, 'http://localhost').pathname;
  try {
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return json(response, 200, listProjects.all());
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readInput(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(response, 201, getProject.get(Number(result.lastInsertRowid)));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const projectId = Number(tasksMatch[1]);
      const taskId = tasksMatch[2] ? Number(tasksMatch[2]) : null;
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET' && taskId === null) {
        return json(response, 200, listTasks.all(projectId).map(taskData));
      }
      if (request.method === 'POST' && taskId === null) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        const input = await readInput(request);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const taskId = transaction(() => {
          const result = createTask.run(projectId, title, project.default_priority, projectId);
          rememberCreatedTask.run(result.lastInsertRowid);
          return Number(result.lastInsertRowid);
        });
        return json(response, 201, taskData(getTask.get(projectId, taskId)));
      }
      if (request.method === 'PATCH' && taskId !== null) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        if (!getTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readInput(request);
        if (Object.hasOwn(input ?? {}, 'destination_project_id')) {
          const destinationId = input.destination_project_id;
          if (!Number.isSafeInteger(destinationId) || destinationId <= 0 || destinationId === projectId) {
            return json(response, 400, { error: 'Choose another active destination project' });
          }
          const destination = getProject.get(destinationId);
          if (!destination) return json(response, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(response, 409, { error: 'Archived project' });
          transaction(() => {
            rememberDestination.run(taskId, destinationId, destinationId);
            moveTask.run(taskId, destinationId, destinationId, projectId, taskId);
          });
          return json(response, 200, taskData(getTask.get(destinationId, taskId)));
        }
        if (Object.hasOwn(input ?? {}, 'due_date')) {
          const dueDate = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (dueDate === null || !validDueDate(dueDate)) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          updateTaskDueDate.run(dueDate, projectId, taskId);
          return json(response, 200, taskData(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input ?? {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          updateTaskPriority.run(input.priority, projectId, taskId);
          return json(response, 200, taskData(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input ?? {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(response, 200, taskData(getTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') return json(response, 400, { error: 'Completed must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(response, 200, taskData(getTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = getProject.get(Number(projectMatch[1]));
      return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectMatch) {
      const projectId = Number(projectMatch[1]);
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      const input = await readInput(request);
      if (Object.hasOwn(input ?? {}, 'default_priority')) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        updateDefaultPriority.run(input.default_priority, projectId);
        return json(response, 200, getProject.get(projectId));
      }
      if (Object.hasOwn(input ?? {}, 'name')) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectId);
        return json(response, 200, getProject.get(projectId));
      }
      if (typeof input?.archived !== 'boolean') return json(response, 400, { error: 'Archived must be a boolean' });
      updateProject.run(Number(input.archived), projectId);
      return json(response, 200, getProject.get(projectId));
    }
    if (request.method === 'GET' && assets.has(path)) {
      const [type, content] = assets.get(path);
      response.writeHead(200, { 'Content-Type': type });
      return response.end(content);
    }
    if (request.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path))) {
      response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return response.end(page);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    json(response, 500, { error: 'Unable to complete request' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
function shutdown() {
  server.close(() => {
    database.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { validDueDate } from './date.js';

const list = document.querySelector('#project-list');
const detail = document.querySelector('#project-detail');
const projects = document.querySelector('#projects');
const projectFilter = document.querySelector('#project-filter');
const projectSearchForm = document.querySelector('#search-projects');
const projectSearch = document.querySelector('#project-search');
const form = document.querySelector('#create-project');
const input = document.querySelector('#project-name');
const error = document.querySelector('#error');
const renameForm = document.querySelector('#rename-project');
const renameInput = document.querySelector('#new-project-name');
const taskForm = document.querySelector('#create-task');
const taskInput = document.querySelector('#task-title');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const taskSearchForm = document.querySelector('#search-tasks');
const taskSearch = document.querySelector('#task-search');
const dueRangeForm = document.querySelector('#due-range');
const dueFrom = document.querySelector('#due-from');
const dueThrough = document.querySelector('#due-through');
const defaultPriority = document.querySelector('#default-task-priority');
const tasksContainer = document.querySelector('#tasks');
const projectMatch = window.location.pathname.match(/^\/projects\/(\d+)$/);
const tasksPath = projectMatch ? `/api/projects/${projectMatch[1]}/tasks` : null;
let appliedDueFrom = '';
let appliedDueThrough = '';
let appliedProjectQuery = '';
let appliedTaskQuery = '';
let tasks = [];
let projectData = [];
let archived = false;
let savedDefaultPriority = 'Normal';

function showError(message = '') {
  error.textContent = message;
  error.hidden = !message;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function projectRow(project) {
  const row = document.createElement('div');
  row.className = 'project-row';
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'Open project';
  button.addEventListener('click', () => {
    window.location.assign(`/projects/${project.id}`);
  });
  const archiveButton = document.createElement('button');
  archiveButton.type = 'button';
  archiveButton.textContent = project.archived ? 'Restore project' : 'Archive project';
  archiveButton.addEventListener('click', async () => {
    archiveButton.disabled = true;
    showError();
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      projectData = projectData.map((item) => item.id === saved.id ? saved : item);
      renderProjects();
    } catch (failure) {
      showError(failure.message);
      archiveButton.disabled = false;
    }
  });
  row.append(name, summary, button, archiveButton);
  return row;
}

function normalizeSearch(value) {
  return value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, (letter) => letter.toLowerCase());
}

function renderProjects() {
  const filtered = projectData.filter((project) =>
    Boolean(project.archived) === (projectFilter.value === 'Archived')
    && normalizeSearch(project.name).includes(appliedProjectQuery));
  projects.replaceChildren(...filtered.map(projectRow));
}

projectFilter.addEventListener('change', renderProjects);
projectSearchForm.addEventListener('submit', (event) => {
  event.preventDefault();
  projectSearch.value = projectSearch.value.trim();
  appliedProjectQuery = normalizeSearch(projectSearch.value);
  showError();
  renderProjects();
});
taskSearchForm.addEventListener('submit', (event) => {
  event.preventDefault();
  taskSearch.value = taskSearch.value.trim();
  appliedTaskQuery = normalizeSearch(taskSearch.value);
  showError();
  renderTasks();
});

function taskRow(task) {
  const row = document.createElement('div');
  row.className = 'task-row';
  row.dataset.testid = 'task-row';
  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `task-${task.id}`;
  checkbox.checked = task.completed;
  checkbox.disabled = archived;
  checkbox.setAttribute('aria-label', `Complete ${task.title}`);
  const title = document.createElement('label');
  title.htmlFor = checkbox.id;
  title.textContent = task.title;
  checkbox.addEventListener('change', async () => {
    if (archived) return;
    checkbox.disabled = true;
    showError();
    try {
      const saved = await request(`${tasksPath}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ completed: checkbox.checked }),
      });
      tasks = tasks.map((item) => item.id === saved.id ? saved : item);
      renderTasks();
    } catch (failure) {
      checkbox.checked = task.completed;
      showError(failure.message);
    } finally {
      checkbox.disabled = archived;
    }
  });
  const renameTaskForm = document.createElement('form');
  renameTaskForm.className = 'rename-task';
  const renameLabel = document.createElement('label');
  const renameTitle = document.createElement('input');
  renameTitle.type = 'text';
  renameTitle.id = `new-task-title-${task.id}`;
  renameTitle.value = task.title;
  renameTitle.disabled = archived;
  renameLabel.htmlFor = renameTitle.id;
  renameLabel.textContent = 'New task title';
  const renameButton = document.createElement('button');
  renameButton.type = 'submit';
  renameButton.textContent = 'Rename task';
  renameButton.disabled = archived;
  const controls = document.createElement('div');
  controls.className = 'form-controls';
  controls.append(renameTitle, renameButton);
  renameTaskForm.append(renameLabel, controls);
  renameTaskForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (archived) return;
    const newTitle = renameTitle.value.trim();
    if (!newTitle) return showError('Task title is required');
    showError();
    renameButton.disabled = true;
    try {
      const saved = await request(`${tasksPath}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: newTitle }),
      });
      tasks = tasks.map((item) => item.id === saved.id ? saved : item);
      renderTasks();
    } catch (failure) {
      showError(failure.message);
    } finally {
      renameButton.disabled = archived;
    }
  });
  const priorityControls = document.createElement('div');
  priorityControls.className = 'task-priority';
  const priorityLabel = document.createElement('label');
  const priority = document.createElement('select');
  priority.id = `task-priority-${task.id}`;
  priorityLabel.htmlFor = priority.id;
  priorityLabel.textContent = 'Task priority';
  for (const value of ['Low', 'Normal', 'High']) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    priority.append(option);
  }
  priority.value = task.priority;
  priority.disabled = archived;
  priority.addEventListener('change', async () => {
    if (archived) return;
    priority.disabled = true;
    showError();
    try {
      const saved = await request(`${tasksPath}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority: priority.value }),
      });
      tasks = tasks.map((item) => item.id === saved.id ? saved : item);
      renderTasks();
    } catch (failure) {
      priority.value = task.priority;
      showError(failure.message);
    } finally {
      priority.disabled = archived;
    }
  });
  priorityControls.append(priorityLabel, priority);
  const dueDateForm = document.createElement('form');
  dueDateForm.className = 'task-due-date';
  const dueDateLabel = document.createElement('label');
  const dueDate = document.createElement('input');
  dueDate.type = 'text';
  dueDate.id = `task-due-date-${task.id}`;
  dueDate.value = task.due_date || '';
  dueDate.disabled = archived;
  dueDateLabel.htmlFor = dueDate.id;
  dueDateLabel.textContent = 'Task due date';
  const saveDueDate = document.createElement('button');
  saveDueDate.type = 'submit';
  saveDueDate.textContent = 'Save due date';
  saveDueDate.disabled = archived;
  const dueDateControls = document.createElement('div');
  dueDateControls.className = 'form-controls';
  dueDateControls.append(dueDate, saveDueDate);
  dueDateForm.append(dueDateLabel, dueDateControls);
  dueDateForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (archived) return;
    showError();
    saveDueDate.disabled = true;
    try {
      const saved = await request(`${tasksPath}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ due_date: dueDate.value.trim() }),
      });
      tasks = tasks.map((item) => item.id === saved.id ? saved : item);
      renderTasks();
    } catch (failure) {
      showError(failure.message);
    } finally {
      saveDueDate.disabled = archived;
    }
  });
  const moveForm = document.createElement('form');
  moveForm.className = 'move-task';
  const destinationLabel = document.createElement('label');
  const destination = document.createElement('select');
  destination.id = `destination-project-${task.id}`;
  destinationLabel.htmlFor = destination.id;
  destinationLabel.textContent = 'Destination project';
  const eligibleProjects = projectData.filter((project) => !project.archived && project.id !== Number(projectMatch[1]));
  for (const project of eligibleProjects) {
    const option = document.createElement('option');
    option.value = String(project.id);
    option.textContent = project.name;
    destination.append(option);
  }
  if (eligibleProjects.length) destination.value = String(eligibleProjects[0].id);
  const movingDisabled = archived || !eligibleProjects.length;
  destination.disabled = movingDisabled;
  const moveButton = document.createElement('button');
  moveButton.type = 'submit';
  moveButton.textContent = 'Move task';
  moveButton.disabled = movingDisabled;
  const moveControls = document.createElement('div');
  moveControls.className = 'form-controls';
  moveControls.append(destination, moveButton);
  moveForm.append(destinationLabel, moveControls);
  moveForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (movingDisabled) return;
    moveButton.disabled = true;
    destination.disabled = true;
    showError();
    try {
      await request(`${tasksPath}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ destination_project_id: Number(destination.value) }),
      });
      tasks = tasks.filter((item) => item.id !== task.id);
      renderTasks();
    } catch (failure) {
      showError(failure.message);
    } finally {
      moveButton.disabled = movingDisabled;
      destination.disabled = movingDisabled;
    }
  });
  row.append(checkbox, title, renameTaskForm, priorityControls, dueDateForm, moveForm);
  return row;
}

function renderTasks() {
  const filtered = tasks.filter((task) => {
    const matchesCompletion = taskFilter.value === 'All'
      || (taskFilter.value === 'Completed' ? task.completed : !task.completed);
    const matchesPriority = priorityFilter.value === 'All' || task.priority === priorityFilter.value;
    const matchesDueRange = (!appliedDueFrom && !appliedDueThrough)
      || (Boolean(task.due_date)
        && (!appliedDueFrom || task.due_date >= appliedDueFrom)
        && (!appliedDueThrough || task.due_date <= appliedDueThrough));
    const matchesSearch = normalizeSearch(task.title).includes(appliedTaskQuery);
    return matchesCompletion && matchesPriority && matchesDueRange && matchesSearch;
  });
  tasksContainer.replaceChildren(...filtered.map(taskRow));
}

dueRangeForm.addEventListener('submit', (event) => {
  event.preventDefault();
  const from = dueFrom.value.trim();
  const through = dueThrough.value.trim();
  if (!validDueDate(from) || !validDueDate(through)) {
    return showError('Due range must use valid YYYY-MM-DD dates');
  }
  if (from && through && from > through) {
    return showError('Due from must not be after Due through');
  }
  appliedDueFrom = from;
  appliedDueThrough = through;
  dueFrom.value = from;
  dueThrough.value = through;
  showError();
  renderTasks();
});

taskFilter.addEventListener('change', renderTasks);
